WITH enriched AS (SELECT *, SUM(budget) OVER (ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_budget, AVG(budget) OVER (ORDER BY budget, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS budget_avg_6_prior FROM departments) SELECT location, COUNT(CASE WHEN dept_name = 'HR' THEN 1 END) AS hr_count, COUNT_IF(dept_name = 'Engineering') AS engineering_events, COUNT(*) AS event_count, COUNT(DISTINCT id) AS distinct_ids, COUNT_IF(dept_name = 'Legal') AS legal_events, SUM(budget) FILTER (WHERE location = 'Chiang Mai') AS chiang_mai_total_budget FROM enriched GROUP BY location ORDER BY hr_count DESC NULLS LAST;
